export function getProductBySlug(slug) {
  return products.find((p) => p.slug === slug);
}

export function getProductsByCollection(collection) {
  return products.filter((p) => p.collection === collection);
}

export function getProductsByCategory(categorySlug) {
  return products.filter((p) => p.category === categorySlug);
}

export function getProductsBySubcategory(categorySlug, subcategorySlug) {
  return products.filter(
    (p) => p.category === categorySlug && p.subcategory === subcategorySlug
  );
}

export function getRelatedProducts(productSlug, limit = 4) {
  const product = products.find((p) => p.slug === productSlug);
  if (!product) return [];
  return products
    .filter((p) => p.slug !== productSlug && p.category === product.category)
    .slice(0, limit);
}

export function getAllCategories() {
  const categories = new Set();
  products.forEach(p => categories.add(p.category));
  return Array.from(categories);
}

export function getAllSubcategories(categorySlug) {
  const subcategories = new Set();
  products
    .filter(p => p.category === categorySlug)
    .forEach(p => subcategories.add(p.subcategory));
  return Array.from(subcategories);
}
